parameters.jsonBody:
={
  "model": "gpt-4o-mini-2024-07-18",
  "messages": [
    {
      "role": "system",
      "content": "You are an intelligent intent parser for Gorgias ticket management. Extract user intent and available context.\n\nCRITICAL: You MUST output valid JSON matching the exact schema.\n\nAVAILABLE ACTIONS:\n- ask_clarification - Ask user for missing information\n- analyze_insights - Get ticket analytics with recurring patterns\n- list_metrics - Get agent performance stats\n- get_customer - Get customer by ID or email\n- find_user - Find user by name or email\n- list_customers - List all customers\n- get_ticket - Get single ticket by ID\n- list_tickets - List tickets with filters\n- search_tickets - Search with query, date filters\n- create_ticket - Create new ticket\n- close_ticket - Close a ticket\n- set_status - Set ticket status\n- assign_ticket - Assign ticket to agent\n- set_priority - Set ticket priority\n- add_tags - Add tags to ticket\n- remove_tags - Remove tags from ticket\n- reply_public - Send public reply\n- comment_internal - Add internal note\n\nOUTPUT FORMAT (JSON ONLY):\n{\n  \"plan\": [\n    {\n      \"step\": 1,\n      \"action\": \"action_name\",\n      \"ticket_id\": \"123\",\n      \"status\": \"open\",\n      \"priority\": \"urgent\",\n      \"customer_email\": \"user@example.com\",\n      \"query\": \"search term\",\n      \"message\": \"text\",\n      \"limit\": 50\n    }\n  ]\n}\n\nEXAMPLES:\n\nUser: \"show open tickets\"\n→ {\"plan\": [{\"step\": 1, \"action\": \"list_tickets\", \"status\": \"open\", \"limit\": 50}]}\n\nUser: \"get ticket 226392965\"\n→ {\"plan\": [{\"step\": 1, \"action\": \"get_ticket\", \"ticket_id\": \"226392965\"}]}\n\nUser: \"set priority to urgent\" (no context)\n→ {\"plan\": [{\"step\": 1, \"action\": \"ask_clarification\", \"question\": \"Which ticket would you like to set to urgent? Please provide the ticket ID.\"}]}"
    },
    {
      "role": "user",
      "content": "={{ $('Parse Slack').first().json.user_text }}"
    }
  ],
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "name": "gorgias_plan",
      "strict": true,
      "schema": {
        "type": "object",
        "properties": {
          "plan": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "step": {
                  "type": "number",
                  "description": "Step number in the plan"
                },
                "action": {
                  "type": "string",
                  "description": "Action to perform",
                  "enum": [
                    "ask_clarification",
                    "analyze_insights",
                    "list_metrics",
                    "get_customer",
                    "find_user",
                    "list_customers",
                    "get_ticket",
                    "list_tickets",
                    "search_tickets",
                    "create_ticket",
                    "close_ticket",
                    "set_status",
                    "assign_ticket",
                    "set_priority",
                    "add_tags",
                    "remove_tags",
                    "reply_public",
                    "comment_internal"
                  ]
                },
                "question": {
                  "type": "string",
                  "description": "Clarification question (for ask_clarification action)"
                },
                "period": {
                  "type": "string",
                  "description": "Time period for analytics (for analyze_insights action)",
                  "enum": ["7d", "30d", "90d"]
                },
                "focus": {
                  "type": "string",
                  "description": "Focus area for analytics (for analyze_insights action)",
                  "enum": ["questions", "performance", "tags", "all"]
                },
                "ticket_id": {
                  "type": "string",
                  "description": "Ticket ID (if applicable)"
                },
                "customer_id": {
                  "type": "string",
                  "description": "Customer ID (if applicable)"
                },
                "customer_email": {
                  "type": "string",
                  "description": "Customer email address (if applicable)"
                },
                "name": {
                  "type": "string",
                  "description": "Person name for search (if applicable)"
                },
                "query": {
                  "type": "string",
                  "description": "Search query (if applicable)"
                },
                "date_from": {
                  "type": "string",
                  "description": "Start date for filtering (ISO 8601 format)"
                },
                "date_to": {
                  "type": "string",
                  "description": "End date for filtering (ISO 8601 format)"
                },
                "status": {
                  "type": "string",
                  "description": "Ticket status filter",
                  "enum": ["open", "closed", "pending", "all"]
                },
                "priority": {
                  "type": "string",
                  "description": "Ticket priority",
                  "enum": ["low", "normal", "high", "urgent"]
                },
                "limit": {
                  "type": "number",
                  "description": "Number of results to return"
                },
                "cursor": {
                  "type": "string",
                  "description": "Pagination cursor"
                },
                "page": {
                  "type": "number",
                  "description": "Page number for pagination"
                },
                "assignee_email": {
                  "type": "string",
                  "description": "Assignee email address (if applicable)"
                },
                "tags": {
                  "type": "string",
                  "description": "Comma-separated tags (if applicable)"
                },
                "message": {
                  "type": "string",
                  "description": "Message text (if applicable)"
                },
                "subject": {
                  "type": "string",
                  "description": "Ticket subject (if applicable)"
                }
              },
              "required": ["step", "action"],
              "additionalProperties": false
            }
          }
        },
        "required": ["plan"],
        "additionalProperties": false
      }
    }
  },
  "temperature": 0.1,
  "max_tokens": 2000
}
